const items = $input.all();
const item = items[0];

try {
  const diagnostics = {
    jsonTopLevelKeys: Object.keys(item.json || {}),
    jsonBodyKeys: Object.keys(item.json?.body || {}),
    binaryKeys: Object.keys(item.binary || {}),
    hasBinary: !!item.binary,
    jsonBodyFileType: typeof item.json?.body?.file,
    jsonBodyFileKeys: item.json?.body?.file && typeof item.json.body.file === 'object'
      ? Object.keys(item.json.body.file)
      : null,
  };

  let resumeText = '';
  let fileName = '';
  let fileContent = '';
  let sourcePath = '';

  if (item.binary?.file) {
    sourcePath = 'item.binary.file';
    const fileData = item.binary.file;
    fileName = fileData.fileName || fileData.filename || 'resume';
    fileContent = fileData.data || '';
    diagnostics.binaryFileMeta = {
      mimeType: fileData.mimeType,
      fileSize: fileData.fileSize,
      fileName: fileData.fileName,
    };
  } else if (item.json?.body?.file && typeof item.json.body.file === 'object') {
    sourcePath = 'item.json.body.file (object)';
    const fileData = item.json.body.file;
    fileName = fileData.filename || fileData.originalname || fileData.name || 'resume';
    fileContent = fileData.data || fileData.content || '';
    diagnostics.bodyFileMeta = fileData;
  } else if (typeof item.json?.body?.file === 'string' && item.json.body.file.length > 100) {
    sourcePath = 'item.json.body.file (base64 string)';
    fileName = item.json.body.filename || item.json.body.fileName || 'resume';
    fileContent = item.json.body.file;
  } else {
    return [{
      json: {
        error: 'No file found in any expected location',
        diagnostics,
        resumeText: '',
        provider: item.json?.body?.provider || item.json?.provider || 'claude',
        fileName: ''
      }
    }];
  }

  diagnostics.sourcePath = sourcePath;
  diagnostics.fileContentLength = fileContent.length;
  diagnostics.fileName = fileName;

  const buffer = Buffer.from(fileContent, 'base64');
  const isPDF = buffer.slice(0, 4).toString('ascii') === '%PDF';
  diagnostics.detectedType = isPDF ? 'PDF' : 'other';
  diagnostics.bufferByteLength = buffer.length;

  let rawText = '';

  if (isPDF) {
    const pdfString = buffer.toString('latin1');
    const streamMatches = pdfString.match(/stream[\r\n]([\s\S]*?)endstream/g) || [];
    const textParts = [];

    for (const stream of streamMatches) {
      const tjMatches = stream.match(/\(([^)\\]*(?:\\.[^)\\]*)*)\)\s*(?:Tj|'|")/g) || [];
      for (const m of tjMatches) {
        const text = m.replace(/^\(/, '').replace(/\)\s*(?:Tj|'|")$/, '')
          .replace(/\\n/g, ' ').replace(/\\r/g, ' ').replace(/\\\\/g, '\\')
          .replace(/\\[()]/g, c => c[1]);
        if (text.trim()) textParts.push(text);
      }

      const hexMatches = stream.match(/<([0-9a-fA-F]+)>\s*(?:Tj|'|")/g) || [];
      for (const m of hexMatches) {
        const hex = m.match(/<([0-9a-fA-F]+)>/)[1];
        let text = '';
        for (let i = 0; i < hex.length; i += 2) {
          text += String.fromCharCode(parseInt(hex.substr(i, 2), 16));
        }
        if (text.trim()) textParts.push(text);
      }

      const tjArrayMatches = stream.match(/\[([^\]]+)\]\s*TJ/g) || [];
      for (const m of tjArrayMatches) {
        const parts = m.match(/\(([^)\\]*(?:\\.[^)\\]*)*)\)/g) || [];
        for (const p of parts) {
          const text = p.slice(1, -1).replace(/\\[nr]/g, ' ');
          if (text.trim()) textParts.push(text);
        }
      }
    }

    rawText = textParts.join(' ');
  } else {
    rawText = buffer.toString('utf-8');
  }

  let resumeText = rawText
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (resumeText.length < 50 && (fileName.includes('.docx') || fileName.includes('.doc'))) {
    const xmlMatches = rawText.match(/<w:t[^>]*>([^<]+)<\/w:t>/g) || [];
    resumeText = xmlMatches
      .map(m => m.replace(/<[^>]+>/g, ''))
      .join(' ')
      .trim();
  }

  diagnostics.extractedTextLength = resumeText.length;
  diagnostics.extractedTextPreview = resumeText.slice(0, 200);

  const provider = (item.json?.body?.provider || item.json?.provider || 'claude').toString().toLowerCase();

  return [{
    json: {
      resumeText: resumeText || 'No text extracted from file',
      provider,
      fileName,
      diagnostics
    }
  }];

} catch (error) {
  return [{
    json: {
      error: 'Extraction failed: ' + error.message,
      resumeText: '',
      provider: 'claude',
      fileName: ''
    }
  }];
}

const resumeText = $json.resumeText;

const prompt = `Extract structured information from this resume. Return ONLY valid JSON with no markdown formatting or code blocks.

Resume:
${resumeText}

Return this exact structure:
{
  "skills": ["skill1", "skill2"],
  "experience": [
    {
      "title": "Job Title",
      "company": "Company Name",
      "duration": "2020-2023",
      "highlights": ["achievement1", "achievement2"]
    }
  ],
  "education": [
    {
      "degree": "Degree Name",
      "institution": "School Name",
      "year": "2020"
    }
  ]
}`;

return [{
  json: {
    prompt: prompt,
    resumeText: resumeText
  }
}];

const resumeText = $json.resumeText;

const prompt = `Extract structured information from this resume. Return ONLY valid JSON with no markdown formatting or code blocks.

Resume:
${resumeText}

Return this exact structure:
{
  "skills": ["skill1", "skill2"],
  "experience": [
    {
      "title": "Job Title",
      "company": "Company Name",
      "duration": "2020-2023",
      "highlights": ["achievement1", "achievement2"]
    }
  ],
  "education": [
    {
      "degree": "Degree Name",
      "institution": "School Name",
      "year": "2020"
    }
  ]
}`;

return [{
  json: {
    prompt: prompt,
    resumeText: resumeText
  }
}];

// Get the response from either Claude or Ollama
let responseText = '';

// Check which provider was used
if ($json.content) {
  // Claude response
  responseText = $json.content[0].text;
} else if ($json.response) {
  // Ollama response
  responseText = $json.response;
} else {
  return [{
    json: {
      error: 'Unknown response format',
      skills: [],
      experience: [],
      education: []
    }
  }];
}

// Strip markdown code fences
const cleaned = responseText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

try {
  // Parse the JSON
  const parsed = JSON.parse(cleaned);

  return [{
    json: {
      skills: parsed.skills || [],
      experience: parsed.experience || [],
      education: parsed.education || []
    }
  }];
} catch (error) {
  return [{
    json: {
      error: 'Failed to parse JSON: ' + error.message,
      rawResponse: cleaned,
      skills: [],
      experience: [],
      education: []
    }
  }];
}
